def minDifference(n, k):
    divs = [d for d in range(1, n + 1) if n % d == 0]
    best = [None, float('inf')]
    path = []

    def dfs(rem, left, lo):
        if left == 1:
            if rem >= lo:
                cand = path + [rem]
                diff = cand[-1] - cand[0]
                if diff < best[1]:
                    best[0], best[1] = cand, diff
            return
        for d in divs:
            if d < lo:
                continue
            if d ** left > rem:
                break
            if rem % d == 0:
                path.append(d)
                dfs(rem // d, left - 1, d)
                path.pop()

    dfs(n, k, 1)
    return best[0]
